local({
  rel <- as.numeric(haven::zap_labels(parent_relation))
  case_when(
    rel %in% c(1, 3, 5, 7, 9) ~ "Mother",
    rel %in% c(2, 4, 6, 8, 10) ~ "Father",
    rel %in% 11:16 ~ "Other carer",
    rel == -2 ~ "Unknown",
    .default = NA_character_
  )
})

local({
  k <- cbind(
    as.numeric(parent_checks_homework),
    as.numeric(parent_knows_whereabouts),
    as.numeric(parent_enforces_curfew)
  )
  k[!(k %in% 1:4)] <- NA
  rowMeans(k)
})

local({
  wd <- coalesce(
    if_else(as.numeric(tv_wd_hours) %in% 0:6, as.numeric(tv_wd_hours), NA_real_),
    recode_values(as.numeric(tv_wd_band), 1 ~ 0, 2 ~ 0.5, 3 ~ 1.5, 4 ~ 2.5, 5 ~ 4, 6 ~ 5)
  )
  we <- coalesce(
    if_else(as.numeric(tv_we_hours) %in% 0:6, as.numeric(tv_we_hours), NA_real_),
    recode_values(as.numeric(tv_we_band), 1 ~ 0, 2 ~ 0.5, 3 ~ 1.5, 4 ~ 2.5, 5 ~ 4, 6 ~ 5)
  )
  (5 * wd + 2 * we) / 7
})

